package com.householdfinance.finance.adapter.config;import com.householdfinance.finance.application.port.in.*;import com.householdfinance.finance.application.port.out.FinanceRepository;import com.householdfinance.finance.application.port.out.IdempotencyRepository;import com.householdfinance.finance.application.service.ServiceFactory;import org.springframework.context.annotation.*;@Configuration public class FinanceConfig{@Bean HouseholdUseCase households(FinanceRepository r){return ServiceFactory.household(r);}@Bean AccountUseCase accounts(FinanceRepository r){return ServiceFactory.account(r);}@Bean TransactionUseCase transactions(FinanceRepository r){return ServiceFactory.transaction(r);}@Bean BillUseCase bills(FinanceRepository r,IdempotencyRepository i){return ServiceFactory.bill(r,i);}@Bean BudgetUseCase budgets(FinanceRepository r){return ServiceFactory.budget(r);}@Bean ReportUseCase reports(FinanceRepository r){return ServiceFactory.report(r);}@Bean CreditCardUseCase cards(FinanceRepository r){return ServiceFactory.card(r);}@Bean CategoryUseCase categories(FinanceRepository r){return ServiceFactory.category(r);}}
